class Gradebook:
    def __init__(self) -> None:
        # assignment name -> (weight, kind)
        self.assignments = {}
        # student -> {assignment name -> grade}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError("kind must be 'homework' or 'quiz'")
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if grade < 2.0 or grade > 5.0:
            raise ValueError("grade must be between 2.0 and 5.0")
        if assignment not in self.assignments:
            raise ValueError(f"unknown assignment: {assignment}")
        self.grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        student_grades = self.grades.get(student, {})

        # Determine which assignment to drop: lowest quiz grade if >1 quiz.
        quiz_names = [
            name for name, (_, kind) in self.assignments.items() if kind == "quiz"
        ]
        quizzes_taken = [
            (name, student_grades[name]) for name in quiz_names if name in student_grades
        ]
        drop = None
        if len(quizzes_taken) > 1:
            drop = min(quizzes_taken, key=lambda item: item[1])[0]

        total_weight = 0.0
        weighted_sum = 0.0
        for name, (weight, _) in self.assignments.items():
            if name == drop:
                continue
            grade = student_grades.get(name, 2.0)
            weighted_sum += weight * grade
            total_weight += weight

        if total_weight == 0:
            return 0.0
        return round(weighted_sum / total_weight, 2)
```

